-- ============================================================================
-- PRODUCTION: replace the opportunity questions with the reviewed set (QUAL/DEMO/PROP/NEG/WON)
-- ============================================================================
-- 1. Old questions in these stages are switched OFF (kept, not deleted), so their saved answers stay in the database.
-- 2. The new questions are added. Existing rows with the same key are never overwritten.
-- 3. Closed-Lost questions are not changed.
-- Safe to run more than once. Run together with the new application code.
-- ============================================================================
BEGIN;
UPDATE questions SET "isActive" = FALSE, "updatedAt" = now()
 WHERE stage IN ('Customer engagement', 'Demonstration', 'Proposal', 'Negotiation', 'Closed-Won') AND "questionKey" NOT IN ('ENG-01', 'ENG-02', 'ENG-03', 'ENG-04', 'ENG-05', 'DEMO-01', 'DEMO-02', 'DEMO-03', 'DEMO-04', 'DEMO-05', 'DEMO-06', 'DEMO-07', 'DEMO-08', 'DEMO-08b', 'DEMO-09', 'DEMO-10', 'DEMO-11', 'DEMO-12', 'PROP-01', 'PROP-02', 'PROP-03', 'PROP-04', 'PROP-05', 'PROP-06', 'PROP-07', 'PROP-08', 'PROP-09', 'NEG-01', 'NEG-02', 'NEG-03', 'NEG-04', 'NEG-05a', 'NEG-05b', 'NEG-05c', 'NEG-05d', 'NEG-06', 'NEG-07', 'NEG-08', 'NEG-09', 'WON-01', 'WON-02', 'WON-03', 'WON-04', 'WON-05', 'WON-06', 'WON-07', 'WON-08') AND "isActive" = TRUE;


SELECT stage, COUNT(*) FILTER (WHERE "isActive") AS active FROM questions GROUP BY stage ORDER BY stage;
COMMIT;
SELECT 'question set replaced' AS status;
